from pathlib import Path

path = Path('/home/ubuntu/portal-acompanhamento-projetos/client/src/pages/Admin.tsx')
text = path.read_text()
start = text.index('function UserManagement(')
end = text.index('\nfunction StageForm(', start)
replacement = '''function UserManagement({ users, areas, onCreate, onUpdate, loading }: { users: any[]; areas: AdminArea[]; onCreate: (input: { openId: string; name: string; email: string; profile: UserProfile; areaIds: number[] }) => void; onUpdate: (id: number, data: { profile?: UserProfile; areaIds?: number[]; isActive?: boolean }) => void; loading: boolean }) {\n  const [openId, setOpenId] = useState("");\n  const [name, setName] = useState("");\n  const [email, setEmail] = useState("");\n  const [profile, setProfile] = useState<UserProfile>("consulta");\n  const [areaIds, setAreaIds] = useState<number[]>([]);\n  const [editingId, setEditingId] = useState<number | null>(null);\n  const [editingProfile, setEditingProfile] = useState<UserProfile>("consulta");\n  const [editingAreaIds, setEditingAreaIds] = useState<number[]>([]);\n  const toggleArea = (setter: React.Dispatch<React.SetStateAction<number[]>>, id: number) => setter(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id]);\n  const profileOptions = USER_PROFILES.map(value => ({ value, label: USER_PROFILE_LABELS[value], description: USER_PROFILE_DESCRIPTIONS[value] }));\n  return <div className="space-y-6">\n    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.4fr)]">\n      <Card><CardHeader><CardTitle className="flex items-center gap-2 text-lg font-black"><UserPlus className="h-5 w-5 text-[#e30613]" />Adicionar usuário</CardTitle></CardHeader><CardContent className="space-y-4">\n        <Field label="Open ID"><Input value={openId} onChange={e => setOpenId(e.target.value)} placeholder="Identificador OAuth" /></Field>\n        <Field label="Nome"><Input value={name} onChange={e => setName(e.target.value)} /></Field>\n        <Field label="E-mail"><Input type="email" value={email} onChange={e => setEmail(e.target.value)} /></Field>\n        <Field label="Perfil"><Select value={profile} onValueChange={value => setProfile(value as UserProfile)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{profileOptions.map(option => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select><p className="mt-1 text-xs text-neutral-500">{USER_PROFILE_DESCRIPTIONS[profile]}</p></Field>\n        {profile === "gestor_setor" && <Field label="Setores vinculados"><div className="grid gap-2 rounded-md border border-neutral-200 bg-neutral-50 p-3">{areas.map(area => <label key={area.id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={areaIds.includes(area.id)} onChange={() => toggleArea(setAreaIds, area.id)} />{area.shortCode ? `${area.shortCode} — ` : ""}{area.name}</label>)}</div></Field>}\n        <Button disabled={loading || !openId || !name || !email} onClick={() => onCreate({ openId, name, email, profile, areaIds })} className="bg-[#e30613] hover:bg-[#c80511]">Cadastrar usuário</Button>\n      </CardContent></Card>\n      <Card><CardHeader><CardTitle className="flex items-center gap-2 text-lg font-black"><ShieldCheck className="h-5 w-5 text-[#e30613]" />Usuários cadastrados</CardTitle><p className="text-sm text-neutral-500">Atribua o perfil e, quando aplicável, os setores sob responsabilidade do usuário.</p></CardHeader><CardContent className="space-y-3">{users.length ? users.map(user => { const currentProfile = (user.profile || (user.role === "admin" ? "admin_geral" : "consulta")) as UserProfile; const isEditing = editingId === user.id; return <div key={user.id} className="rounded-md border border-neutral-200 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="font-bold">{user.name || "Sem nome"}</p><p className="text-xs text-neutral-500">{user.email} · {USER_PROFILE_LABELS[currentProfile]}</p>{user.areaIds?.length ? <p className="mt-1 text-xs text-neutral-500">Setores: {user.areaIds.map((id: number) => areas.find(area => area.id === id)?.shortCode || `#${id}`).join(", ")}</p> : null}</div><div className="flex flex-wrap gap-2"><Button size="sm" variant="outline" onClick={() => { setEditingId(isEditing ? null : user.id); setEditingProfile(currentProfile); setEditingAreaIds(user.areaIds || []); }} disabled={loading}>{isEditing ? "Cancelar" : "Editar perfil"}</Button><Button size="sm" variant={user.isActive === false ? "default" : "outline"} onClick={() => onUpdate(user.id, { isActive: user.isActive === false })} disabled={loading}>{user.isActive === false ? "Ativar" : "Desativar"}</Button></div></div>{isEditing && <div className="mt-4 space-y-3 border-t border-neutral-100 pt-4"><Field label="Perfil"><Select value={editingProfile} onValueChange={value => setEditingProfile(value as UserProfile)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{profileOptions.map(option => <SelectItem key={option.value} value={option.value}>{option.label}</SelectItem>)}</SelectContent></Select></Field>{editingProfile === "gestor_setor" && <Field label="Setores vinculados"><div className="grid gap-2 rounded-md border border-neutral-200 bg-neutral-50 p-3">{areas.map(area => <label key={area.id} className="flex items-center gap-2 text-sm"><input type="checkbox" checked={editingAreaIds.includes(area.id)} onChange={() => toggleArea(setEditingAreaIds, area.id)} />{area.shortCode ? `${area.shortCode} — ` : ""}{area.name}</label>)}</div></Field>}<Button size="sm" className="bg-[#171717]" disabled={loading} onClick={() => { onUpdate(user.id, { profile: editingProfile, areaIds: editingAreaIds }); setEditingId(null); }}>Salvar perfil</Button></div>}</div>; }) : <p className="text-sm text-neutral-500">Nenhum usuário encontrado.</p>}</CardContent></Card>\n    </div>\n  </div>;\n}'''
path.write_text(text[:start] + replacement + text[end:])
